// Enters play mode with TaoYuan open so the live GameView renders the scene camera every frame.

System.Type manager = null;
foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) {
    var type = assembly.GetType("XEngine.Editor.GUI.SceneView.EditorSceneManager");
    if (type != null) { manager = type; break; }
}
if (manager == null) return "EditorSceneManager not found.";
bool opened = (bool)manager.GetMethod("OpenScene").Invoke(null, new object[] { "Scenes/TaoYuanBattle.scene" });
if (!opened) return "OpenScene returned false.";

System.Type app = null;
foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) {
    var type = assembly.GetType("XEngine.Editor.Core.EditorApplication");
    if (type != null) { app = type; break; }
}
if (app == null) return "EditorApplication not found.";
// EnterPlayMode is an INSTANCE method on the EditorApplication singleton.
var enter = app.GetMethod("EnterPlayMode", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
if (enter == null) return "EnterPlayMode not found.";

// Open the GameView first: without it the editor keeps its idle throttle (no render -> the play
// loop barely ticks) and runtime_screenshot has no capture target.
System.Type gameViewPanel = null;
foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) {
    var t = assembly.GetType("XEngine.Editor.GUI.Panels.GameViewPanel");
    if (t != null) { gameViewPanel = t; break; }
}
if (gameViewPanel == null) return "GameViewPanel type not found.";
var openMethod = gameViewPanel.GetMethod("Open", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
if (openMethod != null) openMethod.Invoke(null, null);
object? instance = app.GetProperty("Instance", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)?.GetValue(null);
if (instance == null) {
    var instanceField = app.GetField("Instance", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
    instance = instanceField != null ? instanceField.GetValue(null) : null;
}
if (instance == null) return "EditorApplication.Instance not found.";
enter.Invoke(instance, null);
return "entering play mode";

// In play mode (TaoYuanBattle open): renders the live battle camera to a PNG and returns the
// frame stats. Expects the editor already in play mode (enter_play.cs ran first).

var scene = XEngine.Runtime.Resources.Scene.Current;
if (scene == null || scene.Name != "TaoYuanBattle") return "TaoYuanBattle is not the current scene (playing=" + XEngine.Runtime.Application.IsPlaying + ").";

XEngine.Runtime.Camera? battleCamera = null;
int drivers = 0;
System.Type driverType = null;
foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) {
    var t = assembly.GetType("SanGuoXEngine.Battle.SanguoBattleDriver");
    if (t != null) { driverType = t; break; }
}
foreach (var go in scene.AllObjects) {
    foreach (var component in go.GetComponents()) {
        if (component is XEngine.Runtime.Camera c && go.Name == "Battle Camera" && battleCamera == null) battleCamera = c;
        if (driverType != null && driverType.IsInstanceOfType(component)) drivers++;
    }
}
if (battleCamera == null) return "no Battle Camera found.";

string root = XEngine.Editor.Projects.Project.Current.RootPath;
string output = System.IO.Path.Combine(root, "Export/scene/xengine-frames/e2-hud-cache-battle.png");
System.Type studio = null;
foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) {
    var type = assembly.GetType("SanGuoXEngine.Editor.SanguoCaptureStudio");
    if (type != null) { studio = type; break; }
}
var position = battleCamera.Transform.Position;
var rotation = battleCamera.Transform.Rotation;
studio.GetMethod("CaptureSceneFrame").Invoke(null, new object[] {
    battleCamera, position, rotation, 960, 540, output });

var stats = XEngine.Runtime.Rendering.RenderStats.Last;
return "captured play-battle.png | drivers " + drivers
    + " | drawCalls " + stats.DrawCalls + " tris " + stats.Triangles
    + " drawn " + stats.RenderablesDrawn + " lodHidden " + stats.LodRenderersHidden;
